return {api_version=1,id="LOOT_537",name="Leyline Manipulator",text="<b>Battlecry:</b> If you're holding any cards that didn't start in your deck, reduce their Cost by (2).",set="LOOTAPALOOZA",type="minion",class="mage",rarity="rare",cost=4,attack=4,health=5,tags={"elemental"},keywords={"battlecry"},on_battlecry=function(ctx,self)for _,e in ipairs(ctx:hand(ctx:controller(self)))do if not ctx:entity(e).started_in_deck then ctx:modify(e,{stat="cost",operation="add",value=-2})end end end}
